// --- Genuinely un-decodable oneOf (kept as a documented skip) ----------------

// TestOneOfBaseAttributeContentDtoV2 exercises the match-counting
// BaseAttributeContentDtoV2 wrapper — the ONE oneOf in this package that
// cannot be made discriminator-aware.
//
// Every variant of this oneOf has the same shape — {reference?, data} —
// differing only by the Go type of `data`. One variant, ObjectAttributeContentV2,
// types data as interface{} and therefore accepts ANY JSON value. As a result
// every concrete payload strict-decodes into both its intended variant AND
// ObjectAttributeContentV2, yielding match >= 2 and the decoder error
// "data matches more than one schema in oneOf(BaseAttributeContentDtoV2)".
//
// This is exactly tools/fixoneof's knownUnpatchable[BaseAttributeContentDtoV2]
// rationale (the spec defines no discriminator for the V2 content oneOf, unlike
// V3 which has discriminator.propertyName: contentType, and Java's
// AttributeContentDeserializer decodes every V2 variant into the base type).
// No variant of this wrapper can round-trip through the generated decoder, so
// all cases are documented and skipped. The companion happy path is fully
// covered by TestOneOfBaseAttributeContentDtoV3, which exercises the patched
// discriminator-aware decoder for the V3 content oneOf.
func TestOneOfBaseAttributeContentDtoV2(t *testing.T) {
	// Representative payloads, one per distinct `data` Go type. Each is
	// asserted to FAIL with the ambiguous-match error (pinning actual
	// behaviour), then skipped.
	payloads := map[string]string{
		"boolean": `{"data":true}`,
		"string":  `{"data":"hello"}`,
		"integer": `{"data":7}`,
		"float":   `{"data":1.5}`,
		"object":  `{"data":{"any":"thing"}}`,
		"file":    `{"data":{"content":"YQ==","fileName":"f.txt","mimeType":"text/plain"}}`,
	}
	for name, payload := range payloads {
		t.Run(name, func(t *testing.T) {
			var w BaseAttributeContentDtoV2
			err := json.Unmarshal([]byte(payload), &w)
			if err == nil || !strings.Contains(err.Error(), "matches more than one schema") {
				t.Fatalf("BaseAttributeContentDtoV2 %s: expected ambiguous-match error, got err=%v inst=%T",
					name, err, w.GetActualInstance())
			}
			t.Skip("BaseAttributeContentDtoV2 is un-decodable via the generator's " +
				"match-counting oneOf: all variants share the {reference?, data} shape and " +
				"ObjectAttributeContentV2 types data as interface{}, so every payload matches " +
				"at least two variants. See tools/fixoneof knownUnpatchable[BaseAttributeContentDtoV2]. " +
				"Fix: add discriminator.propertyName: contentType to the V2 content oneOf in the spec " +
				"(as V3 already has). The V3 equivalent is fully covered by TestOneOfBaseAttributeContentDtoV3.")
		})
	}
}
